from ta_egate_cmd_parser.interface import EgateCmdParser


class ta_egate_cmd_parser(EgateCmdParser):
    """
    Library for executing commands on EGATE console.
    """
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'
    ROBOT_LISTENER_API_VERSION = 2

    def __new__(cls, *args, **kwargs):
        if not hasattr(cls, '_instance'):
            instance = super(ta_egate_cmd_parser, cls).__new__(cls)
            instance.add_egate_connection_parameters(egate_id=0, host='localhost', port=20000)
            cls._instance = instance
        return cls._instance

    def __init__(self, *args, **kwargs):
        """

        :param args:
        :param kwargs:
        """
        super(ta_egate_cmd_parser, self).__init__()
